"node -e "
const fs = require('fs');
const readline = require('readline');

async function main() {
  const filePath = 'C:\\\\Users\\\\lg\\\\Desktop\\\\오늘\\\\(데이터검증팀)실사 DB 취합_전달용_260720_배현명.csv';
